referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  const clone = (v) => JSON.parse(JSON.stringify(v));
  const original = clone(d.value),
    updated = clone(d.value);
  for (const u of d.updates) {
    let n = updated;
    for (let i = 0; i < u.path.length - 1; i++) {
      const k = u.path[i];
      if (!Object.hasOwn(n, k)) n[k] = typeof u.path[i + 1] === "number" ? [] : {};
      n = n[k];
    }
    const k = u.path.at(-1);
    n[k] = u.op === "add" ? n[k] + u.value : clone(u.value);
  }
  return { original, updated };
}

